WITH valid AS (SELECT id, name, email, city, segment, signup_date, is_active, CAST(is_active AS INT) AS is_active_flag, DATE_ADD(signup_date, 73) AS signup_date_plus_73d FROM customers WHERE signup_date > TO_DATE('2023-11-17') AND city IS NOT NULL) SELECT * FROM (SELECT segment, city, is_active_flag FROM valid) src PIVOT (SUM(is_active_flag) AS amount, COUNT(1) AS n FOR city IN ('Singapore', 'Berlin', 'London'));
